        uint256 slope0,
        uint256 slope1,
        uint256 maxMultiplier,
        uint256 minMultiplier,
        uint256 rate,
        uint256 timestamp
    ) public {
        // Bound inputs to valid ranges
        kink = bound(kink, 1, 1e27 - 1);
        slope0 = bound(slope0, 0, 1e27);
        slope1 = bound(slope1, 0, 1e27);
        maxMultiplier = bound(maxMultiplier, 1e27, 1e30);
        minMultiplier = bound(minMultiplier, 0, maxMultiplier - 1);
        rate = bound(rate, 0, 1e27);
        timestamp = bound(timestamp, 1, type(uint256).max);

        // Initialize the contract
        c.initialize(address(this));

        // Set slopes and limits
        C.SlopeData memory slopes = C.SlopeData({kink: kink, slope0: slope0, slope1: slope1});
        c.setSlopes(asset, slopes);
        c.setLimits(maxMultiplier, minMultiplier, rate);

        // Warp to a timestamp
        vm.warp(timestamp);

        // Call rate twice; the second call should have a different elapsed time
        uint256 result1 = c.rate(vault, asset);
        vm.warp(timestamp + 1000);
        uint256 result2 = c.rate(vault, asset);

        // The bug changes the utilization calculation path, which affects the multiplier
        // and rate computation. The rule: the rate should not be zero when slopes and limits are set.
        assertTrue(result1 > 0 && result2 > 0);
    }
}

